import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [productos, setProductos] = useState([]);
  const [ventas, setVentas] = useState([]);
  const [nuevoProducto, setNuevoProducto] = useState({ nombre: '', categoria: '', precio: '', stockActual: '' });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = () => {
    obtenerProductos();
    obtenerVentas();
  };

  const obtenerProductos = async () => {
    const res = await axios.get('http://localhost:8080/api/productos');
    setProductos(res.data);
  };

  const obtenerVentas = async () => {
    const res = await axios.get('http://localhost:8080/api/ventas');
    setVentas(res.data);
  };

  const vender = async (id, cantidad) => {
    try {
      await axios.post(`http://localhost:8080/api/ventas/${id}/${cantidad}`);
      cargarDatos();
    } catch (err) { alert("Error: Stock insuficiente"); }
  };

  // Lógica del Reporte Mensual
  const totalMensual = ventas.reduce((acc, v) => acc + v.total, 0);
  const masVendido = ventas.length > 0 
    ? [...ventas].sort((a,b) => b.cantidad - a.cantidad)[0].productoNombre 
    : "N/A";

  const estilos = {
    cuerpo: { backgroundColor: '#1a120b', color: '#e5e5e5', minHeight: '100vh', padding: '30px', fontFamily: 'Inter, sans-serif' },
    card: { backgroundColor: '#2c1e12', padding: '20px', borderRadius: '15px', border: '1px solid #3c2a1a', marginBottom: '20px' },
    input: { backgroundColor: '#1a120b', color: '#fff', border: '1px solid #d4a373', padding: '10px', borderRadius: '5px', margin: '5px' },
    btnVenta: { backgroundColor: '#d4a373', color: '#1a120b', border: 'none', padding: '5px 10px', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' },
    reporte: { display: 'flex', justifyContent: 'space-around', backgroundColor: '#3c2a1a', padding: '20px', borderRadius: '15px', color: '#d4a373' }
  };

  return (
    <div style={estilos.cuerpo}>
      <header style={{textAlign: 'center', marginBottom: '40px'}}>
        <h1 style={{color: '#d4a373', fontSize: '2.5rem'}}>EL PAISITA UP <span style={{fontSize: '1rem'}}>Dashboard Dark</span></h1>
      </header>

      {/* REPORTE MENSUAL */}
      <div style={estilos.reporte}>
        <div><h3>Total Ventas Mes</h3><p style={{fontSize: '1.5rem', color: '#fff'}}>${totalMensual.toLocaleString()}</p></div>
        <div><h3>Producto Top</h3><p style={{fontSize: '1.5rem', color: '#fff'}}>{masVendido}</p></div>
        <div><h3>Transacciones</h3><p style={{fontSize: '1.5rem', color: '#fff'}}>{ventas.length}</p></div>
      </div>

      <div style={{display: 'flex', gap: '20px', marginTop: '30px'}}>
        {/* COLUMNA INVENTARIO */}
        <div style={{flex: 2}}>
          <div style={estilos.card}>
            <h2>Inventario en Tiempo Real</h2>
            <table style={{width: '100%', textAlign: 'left', borderCollapse: 'collapse'}}>
              <thead><tr style={{color: '#d4a373'}}><th>Producto</th><th>Stock</th><th>Precio</th><th>Acción</th></tr></thead>
              <tbody>
                {productos.map(p => (
                  <tr key={p.id} style={{borderBottom: '1px solid #3c2a1a'}}>
                    <td style={{padding: '10px'}}>{p.nombre}</td>
                    <td style={{color: p.stockActual < 5 ? '#ff4d4d' : '#fff'}}>{p.stockActual}</td>
                    <td>${p.precio}</td>
                    <td><button onClick={() => vender(p.id, 1)} style={estilos.btnVenta}>Vender 1</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* COLUMNA REGISTRO */}
        <div style={{flex: 1}}>
          <div style={estilos.card}>
            <h2>Nuevo Suministro</h2>
            <input style={estilos.input} placeholder="Nombre" name="nombre" onChange={(e) => setNuevoProducto({...nuevoProducto, nombre: e.target.value})} />
            <input style={estilos.input} placeholder="Precio" type="number" onChange={(e) => setNuevoProducto({...nuevoProducto, precio: e.target.value})} />
            <input style={estilos.input} placeholder="Stock" type="number" onChange={(e) => setNuevoProducto({...nuevoProducto, stockActual: e.target.value})} />
            <button style={{...estilos.btnVenta, width: '100%', marginTop: '10px'}} onClick={async () => {
              await axios.post('http://localhost:8080/api/productos', nuevoProducto);
              cargarDatos();
            }}>Guardar</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
